@ConfigurationProperties(prefix = "javaquest.notes")
public class NotesProperties {
    private int maxNotes = 100;
    private String welcomeMessage = "Witaj w JavaQuest Notes Service!";
    // gettery/settery...
}

@SpringBootApplication
@EnableConfigurationProperties(NotesProperties.class)
class NotesApplication { /* ... */ }

@Repository
class NotesRepository {
    private final List<Note> notes = new ArrayList<>();
    private final NotesProperties properties;

    NotesRepository(NotesProperties properties) { this.properties = properties; }

    void add(Note note) {
        if (notes.size() >= properties.getMaxNotes()) {
            throw new IllegalStateException("Osiagnieto limit notatek");
        }
        notes.add(note);
    }
}

@Component
@Profile("dev")
class DevSeedDataRunner implements CommandLineRunner {
    public void run(String... args) {
        repository.add(new Note("1", "[DEV] Notatka testowa"));
    }
}
// @Profile("prod") ProdStartupRunner NIE laduje danych testowych

@Component
class NotesHealthIndicator implements HealthIndicator {
    public Health health() {
        int used = repository.findAll().size();
        int max = properties.getMaxNotes();
        Health.Builder builder = used < max ? Health.up() : Health.down();
        return builder.withDetail("notatki", used + "/" + max).build();
    }
}
